def check_solutions(max_exponent=10):
    solutions = []
    for a in range(1, max_exponent + 1):
        for b in range(1, max_exponent + 1):
            # Calculate the target value for 6^c
            target = (2**a) + (3**b) + 1

            # Check if target is a power of 6
            if target <= 1:
                continue

            c = 0
            temp_target = target
            while temp_target > 1:
                if temp_target % 6 != 0:
                    break
                temp_target //= 6
                c += 1

            if temp_target == 1:
                # Solution found: (a, b, c)
                B = (2**a) + 1
                T = (3**b) + 1
                S = (6**c) + 1

                # Verification check: B + T = S
                if B + T == S:
                    solutions.append({
                        'a': a, 'b': b, 'c': c,
                        'B': B, 'T': T, 'S': S
                    })

    return solutions

solutions = check_solutions()

print("Solutions found (a, b, c):")
for sol in solutions:
    print(f"({sol['a']}, {sol['b']}, {sol['c']}) -> Triple: ({sol['B']}, {sol['T']}, {sol['S']})")

total_sum = sum(s['B'] + s['T'] + s['S'] for s in solutions)
print(f"Total sum of (B+T+S): {total_sum}")

